      "交换机如何学习 MAC 表？未知单播、广播和组播在 VLAN 内怎样转发？",
      "MAC 表老化、MAC 漂移、重复 MAC、虚拟机迁移和网卡绑定冲突分别会带来什么故障特征？",
      "如何用 `ip neigh`、`tcpdump -e`、`bridge fdb` 和交换机 MAC 表排查同网段不通？",
