      "Global、Link-local、ULA、Multicast、Loopback 分别用于什么场景",
      "NDP 替代 IPv4 中哪些机制",
      "ICMPv6 为什么对 IPv6 可用性很关键",
      "双栈环境下访问异常如何排查",
