      "TCP 如何用序列号、ACK、RTO、快速重传、SACK 和按序交付实现可靠传输？",
      "三次握手里初始序列号和 TCP options 如何协商？这些选项对后续传输有什么影响？",
      "TCP 字节流为什么需要应用层 framing？粘包、半包、拆包在协议设计里怎样处理？",
      "流量控制和拥塞控制分别保护什么？`rwnd`、`cwnd`、BDP、慢启动和拥塞避免如何影响吞吐？",
      "`SYN-SENT`、`SYN-RECEIVED`、`ESTABLISHED`、`TIME_WAIT`、`CLOSE_WAIT`、`RST` 分别说明什么线上状态？",
