      "慢启动、拥塞避免、快速重传和快速恢复分别在什么阶段发挥作用？",
      "重复 ACK、SACK、RACK、RTO、ECN 分别给发送端什么拥塞或丢失信号？",
      "为什么 RTO 对吞吐影响通常比快速重传更重？如何从 ACK 时钟和恢复路径解释？",
      "CUBIC、Reno、BBR 的窗口增长、反馈信号、排查表现和适用场景有什么差异？",
