      "治理建议：生产规则按最小权限、分环境、可审计和可回滚设计。为临时白名单设置到期时间，记录规则变更原因，定期清理宽泛网段和过期端口。",
      "参考来源：云安全组状态行为和规则模型参考 AWS 文档；主机防火墙职责参考 Microsoft Learn；IP/TCP 字段基础参考 RFC 791 与 RFC 9293；中文排查思路参考小林 coding。"
